import fs from 'node:fs'
import path from 'node:path'

/**
 * The media directory.
 *
 * Business photographs are files, not rows, so they live here rather than in the
 * repository layer. This is a tiny interface over the filesystem and nothing
 * more: the repository records the metadata, the route orchestrates the two, and
 * this module owns the one thing neither should have to think about — that a
 * storage key is resolved inside the media directory and cannot escape it.
 *
 * The key is always generated by the platform (a fresh id plus an extension read
 * from the file's own bytes), so the traversal guard is a backstop rather than
 * the actual defence. It exists because "the caller cannot influence this" is a
 * property that has a habit of quietly stopping being true.
 */

export function createMediaStore({ dir }) {
  const root = path.resolve(dir)
  fs.mkdirSync(root, { recursive: true })

  function resolve(storageKey) {
    const full = path.resolve(root, storageKey)
    // The separator matters: without it a sibling directory whose name merely
    // starts with the media directory's name would pass the prefix test.
    if (full !== root && !full.startsWith(root + path.sep)) {
      throw new Error(`Refusing to touch a path outside the media directory: ${storageKey}`)
    }
    return full
  }

  return {
    dir: root,

    /** Writes bytes under a key, creating any parent folder. Returns the path. */
    write(storageKey, buffer) {
      const full = resolve(storageKey)
      fs.mkdirSync(path.dirname(full), { recursive: true })
      fs.writeFileSync(full, buffer)
      return full
    },

    /** The bytes for a key, or null when the file is gone. */
    read(storageKey) {
      try {
        return fs.readFileSync(resolve(storageKey))
      } catch (error) {
        if (error.code === 'ENOENT') return null
        throw error
      }
    },

    /**
     * Best-effort removal. A file already gone is the outcome the caller wanted,
     * so it is not an error; the database row is the source of truth and is
     * removed by the repository.
     */
    remove(storageKey) {
      if (!storageKey) return false
      try {
        fs.rmSync(resolve(storageKey), { force: true })
        return true
      } catch {
        return false
      }
    },

    exists(storageKey) {
      return fs.existsSync(resolve(storageKey))
    },
  }
}
